# The pass that plays pickletools-hoversteps.feature: the hover steps and the keyed click that opens the page they look at,
# staged from the repository (the bundle carries the same DLLs; this is the line a suite writes to use them without it).
#
#   scripts/Run-PickleWsl.ps1 -Mod PickleTools -DepMap wsl-deps.hoversteps.map -Filter pickletools-hoversteps
#
# `path:` names a folder of this repository (relative to its root); the folder's own About.xml packageId must match.
nelim.pickletools.hoversteps   path:PickleTools/HoverSteps/Mod
nelim.pickletools.keyedclick   path:PickleTools/KeyedClick/Mod
